const data = msg.payload;

if (!data || typeof data !== "object") {
    return null;
}

msg.device_id = data.device_id;

msg.temperature = Number(data.temperature);
msg.humidity = Number(data.humidity);
msg.pressure = Number(data.pressure);
msg.button_state = Boolean(data.button_state);
msg.timestamp = data.timestamp;

return msg;

if (msg.button_state) {
    msg.payload = "PRESSIONADO";
} else {
    msg.payload = "NÃO PRESSIONADO";
}

return msg;

const deviceId = flow.get("device_id");

if (!deviceId) {
    node.warn("Selecione uma fonte de dados primeiro");
    return null;
}

msg.headers = {
    "Content-Type": "application/json"
};

msg.payload = {
    device_id: deviceId,
    led_state: Boolean(msg.payload),
    updated_by: "node-red"
};

return msg;

if (msg.payload && msg.payload.status === "ok") {
    msg.payload = {
        topic: "status_backend",
        backend_online: true
    };
} else {
    msg.payload = {
        topic: "status_backend",
        backend_online: false
    };
}

return msg;

const deviceId = flow.get("device_id");

if (!deviceId) {
    node.warn("Selecione uma fonte de dados primeiro");
    return null;
}

msg.url =
    "http://127.0.0.1:8000/api/telemetry/latest?device_id=" +
    encodeURIComponent(deviceId);

return msg;

const deviceId = flow.get("device_id");

if (!deviceId) {
    return null;
}

msg.url =
    "http://127.0.0.1:8000/api/actuators/led?device_id=" +
    encodeURIComponent(deviceId);

return msg;

if (
    !msg.payload ||
    typeof msg.payload.led_state !== "boolean"
) {
    return null;
}

msg.payload = msg.payload.led_state;
return msg;

const source = flow.get("source") || "simulator";

let data = msg.payload;

// Converte o JSON em texto para objeto
if (typeof data === "string") {
    try {
        data = JSON.parse(data);
    } catch (err) {
        node.warn("Erro ao converter resposta JSON: " + err.message);
        return null;
    }
}

const expectedDevice =
    flow.get("device_id") || "esp32-simulator-001";

const timestamp = Date.parse(data?.timestamp);
const age = Date.now() - timestamp;

const online =
    !!data &&
    data.device_id === expectedDevice &&
    Number.isFinite(timestamp) &&
    age >= 0 &&
    age <= 15000;

msg.payload = {
    source: source,
    online: online
};

return msg;

const evento = msg.payload;

if (!evento || !evento.evento) {
    return null;
}

let logs = flow.get("eventos_log") || [];

logs.unshift({
    hora: new Date().toLocaleString("pt-BR"),
    evento: evento.evento,
    dispositivo: evento.dispositivo || "-"
});

// Mantém os 200 eventos mais recentes.
logs = logs.slice(0, 200);

flow.set("eventos_log", logs);

msg.payload = logs;
return msg;

const dados = msg.payload;

if (!dados || !dados.source ||
    typeof dados.online !== "boolean") {
    return null;
}

const fonte = dados.source;
const estadoAnterior = context.get("estado_" + fonte) || "desconhecido";

if (dados.online) {
    const timer = context.get("timer_" + fonte);

    if (timer) {
        clearTimeout(timer);
        context.set("timer_" + fonte, null);
    }

    if (estadoAnterior !== "online") {
        context.set("estado_" + fonte, "online");

        msg.payload = {
            evento: "DISPOSITIVO CONECTADO",
            dispositivo: fonte === "real" ? "ESP REAL" : "SIMULATOR"
        };

        return msg;
    }

    return null;
}

if (estadoAnterior !== "online") {
    return null;
}

// Aguarda 30 segundos antes de confirmar a desconexão.
if (!context.get("timer_" + fonte)) {
    const timer = setTimeout(function() {
        context.set("timer_" + fonte, null);
        context.set("estado_" + fonte, "offline");

        node.send({
            payload: {
                evento: "DISPOSITIVO DESCONECTADO",
                dispositivo: fonte === "real" ? "ESP REAL" : "SIMULATOR"
            }
        });
    }, 30000);

    context.set("timer_" + fonte, timer);
}

return null;

const deviceId = msg.device_id || "desconhecido";
const pressionado = msg.button_state === true;

const estadoAnterior =
    context.get("botao_" + deviceId);

context.set("botao_" + deviceId, pressionado);

// Ignora a primeira leitura para não criar evento falso
if (estadoAnterior === undefined) {
    return null;
}

// Só registra quando o estado muda
if (estadoAnterior === pressionado) {
    return null;
}

msg.payload = {
    evento: pressionado
        ? "BOTÃO PRESSIONADO"
        : "BOTÃO SOLTO",
    dispositivo: deviceId
};

return msg;

if (typeof msg.payload !== "boolean") {
    return null;
}

const estado = msg.payload;
const anterior = context.get("estado_led");

context.set("estado_led", estado);

// Primeira leitura: inicializa sem gerar um evento falso.
if (typeof anterior !== "boolean") {
    return null;
}

if (estado === anterior) {
    return null;
}

msg.payload = {
    evento: estado ? "LED ACESO" : "LED APAGADO",
    dispositivo: flow.get("source") === "real"
        ? "ESP REAL"
        : "SIMULATOR"
};

return msg;

if (msg.topic !== "limpar_log") {
    return null;
}

flow.set("eventos_log", []);

msg.topic = "log_limpo_confirmado";
msg.payload = [];

return msg;

const sources = {
    simulator: {
        source: "simulator",
        device_id: "esp32-simulator-001"
    },
    real: {
        source: "real",
        device_id: "esp32-001"
    }
};

const selected = sources[msg.payload];

if (!selected) {
    node.error("Fonte de dados inválida", msg);
    return null;
}

// Guardar a seleção para os demais nós deste flow.
flow.set("source", selected.source);
flow.set("device_id", selected.device_id);

msg.headers = {
    "Content-Type": "application/json"
};

msg.payload = {
    source: selected.source
};

msg.source = selected.source;
msg.device_id = selected.device_id;

return msg;

scope.filteredRows = function () {
    const search = (scope.searchText || "").toLowerCase();

    return scope.rows.filter(function (r) {
        if (scope.deviceFilter &&
            r.device_id !== scope.deviceFilter) return false;

        if (scope.typeFilter &&
            r.record_type !== scope.typeFilter) return false;

        if (scope.buttonFilter !== "") {
            if (r.button_state == null ||
                String(r.button_state) !== scope.buttonFilter) {
                return false;
            }
        }

        if (scope.ledFilter !== "") {
            const ledState = r.record_type === "LED"
                ? String(r.value).toUpperCase() === "ON"
                : r.led_state === true;

            const ledKnown = r.record_type === "LED"
                ? ["ON", "OFF"].includes(String(r.value).toUpperCase())
                : r.led_state === true || r.led_state === false;

            if (!ledKnown || String(ledState) !== scope.ledFilter) {
                return false;
            }
        }

        const text = [
            r.device_id, r.record_type, r.detail,
            r.value, r.updated_by
        ].join(" ").toLowerCase();

        return text.includes(search);
    });
};
